//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::sint::int16_to_float`; the
//! native twin is `benches/native/Bench/Int16ToFloat.lean`.

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::{float, sint};
use lean_runtime_bench::{run, step, SEED};

#[allow(unused_variables)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0.0f64);
    for _ in 0..n {
        x = step(x);
        acc += sint::int16_to_float((x >> 48) as u16);
    }
    float::to_bits(acc) as u64
}

fn main() {
    run(|| (), kernel)
}
